import 'dart:convert';

import 'package:flutter_test/flutter_test.dart';
import 'package:lifehub/core/services/aes_cipher.dart';

/// Known-answer tests: ciphertexts below were generated by the `encrypt`
/// package (AES-256-GCM and legacy AES-256-CBC) with a fixed key/IV. They
/// guarantee vault entries and restore journals written by older builds
/// still decrypt after the migration to package:cryptography.
void main() {
  final key = base64Decode('AQIDBAUGBwgJCgsMDQ4PEBESExQVFhcYGRobHB0eHyA=');
  final ivGcm = base64Decode('AQIDBAUGBwgJCgsM');
  final ivCbc = base64Decode('ERITFBUWFxgZGhscHR4fIA==');
  const plain = 'vault-secret-123 ₱';

  test(
    'decrypts encrypt-package AES-256-GCM output (ct||tag layout)',
    () async {
      final data = await AesCipher.decryptGcm64(
        '2E/Z8URGUIgMz51RzssPFim8cJaJ0lRgZkeV4vAsc+rZe54F',
        key,
        ivGcm,
      );
      expect(data, plain);
    },
  );

  test('decrypts encrypt-package AES-256-CBC output', () async {
    final data = await AesCipher.decryptCbc64(
      'mbJsvtq+azCLWR+fEexndygGiLPS5ltsV7xbrFbKd6I=',
      key,
      ivCbc,
    );
    expect(data, plain);
  });

  test('GCM round-trip produces iv||ct+tag compatible output', () async {
    final key2 = AesCipher.randomKey();
    final iv = AesCipher.randomIv();
    expect(key2.length, 32);
    expect(iv.length, 12);

    final data64 = await AesCipher.encryptGcm64(utf8.encode(plain), key2, iv);
    // ciphertext(19 UTF-8 bytes) + tag(16) = 35 bytes
    expect(base64Decode(data64).length, utf8.encode(plain).length + 16);
    expect(await AesCipher.decryptGcm64(data64, key2, iv), plain);
  });
}
